import React, { useState } from "react";
import { Link } from "react-router-dom";

import "./Style.css";
import { useT } from "../i18n/LanguageContext";

const StarIcon = () => (
  <svg className="rabta-star" viewBox="0 0 40 40" fill="none">
    <path
      d="M20 0 L22.5 17.5 L40 20 L22.5 22.5 L20 40 L17.5 22.5 L0 20 L17.5 17.5 Z"
      fill="white"
    />
  </svg>
);

const GoogleIcon = () => (
  <svg viewBox="0 0 24 24" width="22" height="22">
    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05"/>
    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
  </svg>
);

const AppleIcon = () => (
  <svg viewBox="0 0 24 24" width="22" height="22" fill="white">
    <path d="M18.71 19.5c-.83 1.24-1.71 2.45-3.05 2.47-1.34.03-1.77-.79-3.29-.79-1.53 0-2 .77-3.27.82-1.31.05-2.3-1.32-3.14-2.53C4.25 17 2.94 12.45 4.7 9.39c.87-1.52 2.43-2.48 4.12-2.51 1.28-.02 2.5.87 3.29.87.78 0 2.26-1.07 3.8-.91.65.03 2.47.26 3.64 1.98-.09.06-2.17 1.28-2.15 3.81.03 3.02 2.65 4.03 2.68 4.04-.03.07-.42 1.44-1.38 2.83M13 3.5c.73-.83 1.94-1.46 2.94-1.5.13 1.17-.34 2.35-1.04 3.19-.69.85-1.83 1.51-2.95 1.42-.15-1.15.41-2.35 1.05-3.11z"/>
  </svg>
);

const EmailIcon = () => (
  <svg viewBox="0 0 24 24" width="22" height="22" fill="white">
    <path d="M20 4H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/>
  </svg>
);

export default function RabtaLanding() {
  const [hoveredBtn, setHoveredBtn] = useState(null);
  const t = useT();

  return (
    <div className="body">
      <div className="rabta-bg-noise" />

      <div className="rabta-container">
        <div className="rabta-top">
          <StarIcon />
        </div>

        <div className="rabta-hero">
          <h1 className="rabta-headline">
            <span className="rabta-headline-light">{t("Leaping Over Production")}</span>
            <br />
            <span className="rabta-headline-light">{t("Chaos.")} </span>
            <span className="rabta-headline-bold">{t("Landing on")}</span>
            <br />
            <span className="rabta-headline-accent">{t("Rabta.")}</span>
          </h1>
          <p className="rabta-subline">{t("Clear. Connected. Moving.")}</p>
        </div>

        <div className="rabta-buttons">
          {[
            { id: "google", icon: <GoogleIcon />, label: t("Continue with Google") },
            { id: "apple", icon: <AppleIcon />, label: t("Continue with Apple") },
            { id: "email", icon: <EmailIcon />, label: t("Continue with Email") },
          ].map(({ id, icon, label }) => (
            <button
              key={id}
              className={`rabta-btn ${
                hoveredBtn === id ? "rabta-btn--hovered" : ""
              }`}
              onMouseEnter={() => setHoveredBtn(id)}
              onMouseLeave={() => setHoveredBtn(null)}
            >
              <span className="rabta-btn-icon">{icon}</span>
              <span className="rabta-btn-label">{label}</span>
            </button>
          ))}
        </div>

        {/* ✅ FIXED LOGIN LINK */}
        <p className="rabta-footer-text">
          {t("Already have an account?")}{" "}
          <Link to="/Signin" className="rabta-login-link">
            {t("Log in")}
          </Link>
        </p>
      </div>
    </div>
  );
}
